contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;

        // The call must not revert.
        assert(!reverted);

        // The injected 10 wei must have been added to the pot before any payout:
        // if a payout happened, pot is reset to 0, otherwise pot equals potBefore + 10.
        assert(potAfter == 0 || potAfter == potBefore + amount);

        // Ether conservation: the contract's balance after equals the new pot,
        // except when a payout happened and pot was reset to 0.
        assert(cBalAfter == potAfter || (potAfter == 0 && cBalAfter == 0));
    }

    receive() external payable {}
}

