contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10, "ticket must be exactly 10 wei");
        require(address(this).balance >= amount, "insufficient balance to send ticket");

        uint potBefore = c.pot();
        uint balanceBefore = address(this).balance;

        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();

        if (!reverted) {
            // The payout branch is only observable when pot is reset to zero.
            // In that case the whole pot (potBefore + amount) is paid out:
            // the bank receives FEE_AMOUNT = 1 wei and the caller receives the rest.
            uint paidToCaller = address(this).balance - balanceBefore;
            assert(
                potAfter == 0
                    ? (address(c).balance == 0
                       && paidToCaller >= potBefore + amount - 1
                       && address(c).balance == contractBalanceBefore + amount - (paidToCaller + 1)
                       && paidToCaller + 1 == potBefore + amount)
                    : (potAfter == potBefore + amount
                       && address(c).balance == contractBalanceBefore + amount)
            );
        } else {
            assert(potAfter == potBefore && address(c).balance == contractBalanceBefore);
        }
    }
}

